/// <summary>
/// MET_122589_RPAGeneralLedgerIntegration developed by yadavpa on 25/03/2024
/// RPA Ledger Integration
/// </summary>
[DatacontractAttribute]
public class METRPAGeneralJournalWorkflowSubmissionRequest
{ 
    BatchJournalId    batchJournalId;
    NoYes          	  noYes;
    DataAreaId        dataAreaId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(str _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

[DataMemberAttribute('Journal batch number')]
public BatchJournalId parmBatchJournalId(BatchJournalId _batchJournalId = batchJournalId)
{
    batchJournalId = _batchJournalId;
    return batchJournalId;
}

[DataMemberAttribute('Submit to workflow')]
public NoYes parmSubmitToWorkflow(NoYes _noYes = noYes)
{
    noYes = _noYes;
    return noYes;
}
